def detect_format(activation_dir):
    p = Path(activation_dir)
    if list(p.glob("L*/en_train.npy")):
        return "npy"
    if list(p.glob("layer*_en_train.pt")):
        return "pt_split"
    if list(p.glob("layer*_en.pt")):
        return "pt_flat"
    raise FileNotFoundError(f"No activations found in {activation_dir}")


def discover_layers(activation_dir, fmt):
    p = Path(activation_dir)
    if fmt == "npy":
        return sorted(int(d.name[1:]) for d in p.glob("L*")
                       if (d / "en_train.npy").exists())
    elif fmt == "pt_split":
        return sorted({int(f.stem.split("_")[0].replace("layer", ""))
                       for f in p.glob("layer*_en_train.pt")})
    else:
        return sorted({int(f.stem.split("_")[0].replace("layer", ""))
                       for f in p.glob("layer*_en.pt")})


def discover_languages(activation_dir, fmt, layers):
    p = Path(activation_dir)
    langs = set()
    for layer in layers:
        if fmt == "npy":
            for f in (p / f"L{layer}").glob("*_train.npy"):
                langs.add(f.stem.replace("_train", ""))
        elif fmt == "pt_split":
            for f in p.glob(f"layer{layer}_*_train.pt"):
                name = f.stem.replace(f"layer{layer}_", "").replace("_train", "")
                langs.add(name)
        else:
            for f in p.glob(f"layer{layer}_*.pt"):
                langs.add(f.stem.replace(f"layer{layer}_", ""))
    langs.discard("en")
    return sorted(langs)


def _load_flat_split_indices(activation_dir, n, seed=42, ratio=0.7):
    """Get deterministic split indices for pt_flat format."""
    cache_key = (str(activation_dir), n)
    if cache_key in _SPLIT_CACHE:
        return _SPLIT_CACHE[cache_key]

    split_path = Path(activation_dir) / "split_indices.pt"
    if split_path.exists():
        saved = torch.load(split_path, weights_only=True, map_location="cpu")
        train_idx = [int(i) for i in saved["train"] if int(i) < n]
        eval_idx = [int(i) for i in saved["eval"] if int(i) < n]
    else:
        rng = np.random.RandomState(seed)
        perm = rng.permutation(n)
        n_train = int(n * ratio)
        train_idx = sorted(perm[:n_train].tolist())
        eval_idx = sorted(perm[n_train:].tolist())

    _SPLIT_CACHE[cache_key] = (train_idx, eval_idx)
    return train_idx, eval_idx


