    p = Path(activation_dir)

    if fmt == "npy":
        base = p / f"L{layer}"
        X = np.load(base / f"{lang}_{split}.npy")
        y = np.load(base / f"{lang}_{split}_labels.npy")
    elif fmt == "pt_split":
        data = torch.load(p / f"layer{layer}_{lang}_{split}.pt",
